using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Opponent Selection PREFAB (Assets/_Project/Prefabs/UI/
/// OpponentSelection.prefab, UIPrefabLibrarySO.opponentSelection, generated by Tools > MusicGame > UI >
/// Build All UI Prefabs). The rival cells are instances of the OpponentCell item prefab
/// (UIPrefabLibrarySO.opponentCell) spawned into gridRoot by OpponentSelectionController, one per
/// OpponentRosterSO.opponents entry; the grid's GridLayoutGroup (cell size, spacing, column count) is
/// edited here and the controller only sizes the container to columns × rows.
/// </summary>
public class OpponentSelectionView : MonoBehaviour
{
    [Header("Root")]
    public GameObject      root;
    public TextMeshProUGUI titleText;

    [Header("Grid (OpponentCell instances added at runtime, one per roster entry)")]
    public RectTransform gridRoot;

    [Header("Skip (reveals the precomputed rival at once — never a re-roll)")]
    public Button skipButton;

    [Header("Roulette highlight")]
    public Color normalCellColor = new(1f, 1f, 1f, 0.10f);
    [Tooltip("Alpha of the highlighted cell; its RGB is the current theme's accent colour.")]
    [Range(0f, 1f)] public float highlightAlpha = 0.55f;
    [Tooltip("Accent used when no theme is active.")]
    public Color fallbackAccentColor = new(0.18f, 0.75f, 0.95f);
}
